style.css:
/* Background image */
body {
  background-image: url('https://example.com/youtube_2007_background.jpg');
  background-repeat: repeat-x;
}

/* Button styles */
button, input[type="submit"] {
  background-color: #333;
  color: #fff;
  border: 1px solid #666;
  padding: 5px 10px;
  font-size: 12px;
  font-family: Arial, sans-serif;
}

/* Font family and sizes */
body {
  font-family: Arial, sans-serif;
  font-size: 12px;
}

h1, h2, h3 {
  font-size: 14px;
  color: #00698f;
}

/* Color scheme */
body, button, input[type="submit"] {
  background-color: #f2f2f2;
  color: #333;
}

a {
  color: #00698f;
}

a:hover {
  color: #004d7a;
}
